for(const published of [{"id":"arquivos","title":"Arquivos e permissões","purpose":"Reunir documentos por obra, com pastas, links, uploads e controle de acesso.","before":"Confirme a obra em Obra dos arquivos e escolha Arquivos e pastas em Área da documentação.","steps":["Abra ou crie a pasta e a subpasta de destino.","Use Adicionar documento para enviar um arquivo de até 3 MB ou cadastrar um link; confira título e revisão antes de salvar.","Selecione o documento e abra Visualizar para consultar o original no MARCELL ou adicionar uma nova revisão.","Como administrador, entre na pasta e use Permissões desta pasta: herde o acesso ou escolha Sem acesso, Leitura ou Leitura e edição para cada pessoa."],"result":"O documento aparece na pasta correta, com revisões e histórico; pessoas sem acesso não recebem os registros da pasta.","attention":"Subpastas acumulam restrições das pastas superiores; administradores mantêm acesso. Anexos dos módulos seguem o acesso de origem. As permissões da central não alteram o compartilhamento de links externos no provedor.","example":"Para atualizar uma planta, confira a pasta da obra e a revisão existente. Consulte o histórico para distinguir a planta atual da anterior."},{"id":"arquivos_revisoes","title":"Arquivos · Revisões, busca e comparação","purpose":"Consultar a revisão correta, pesquisar o texto do PDF e comparar duas emissões.","before":"Abra um documento e confira a identificação da revisão atual.","steps":["Em Revisão do documento, selecione a emissão desejada. O aviso de revisão antiga identifica a atual; use Abrir revisão atual para voltar a ela.","Para um PDF com texto, digite uma palavra ou expressão em Buscar no texto do PDF. A busca percorre todas as páginas; use Ir para página no resultado.","Use Comparar revisões e escolha outra emissão em Comparar com a revisão. Cada painel permite consultar, buscar, navegar e baixar seu próprio arquivo.","Use Encerrar comparação para manter a consulta individual ou Fechar visualização para voltar ao cadastro; consulte Histórico de revisões para ver os registros anteriores."],"result":"As duas emissões estão identificadas e o conteúdo corresponde à revisão selecionada.","attention":"A comparação é visual, lado a lado no computador e empilhada no celular; não marca diferenças automaticamente. A busca não faz OCR: PDFs apenas digitalizados podem não ter texto pesquisável. Se o acesso for negado, confira sua sessão e a permissão antes de tentar novamente."},{"id":"arquivos_dossie","title":"Arquivos · Dossiê de licenciamento","purpose":"Organizar as exigências da Prefeitura, do cartório e do condomínio e preparar um pacote documental conferível.","before":"Confirme a obra e escolha Dossiê de licenciamento em Área da documentação. O dossiê usa o mesmo cadastro do módulo Licenciamento.","steps":["Selecione a exigência na lista ou no seletor do celular. Confira a situação e preencha responsável, validade e observações; salve a exigência.","Para exigências condicionais, defina se o item se aplica. Se marcar Não ou Não se aplica, informe uma justificativa. Confira o aviso de documentação faltante.","Use Anexar documento à exigência para um arquivo novo de até 20 MB. Use Enviar nova revisão de… para atualizar o mesmo anexo. O nome padronizado identifica obra, área, item e revisão; o nome original permanece no histórico.","Abra Visualizar anexo e revisões para conferir o conteúdo. O ZIP inclui a revisão atual de cada anexo, incluindo itens adicionais e documentos gerais cadastrados.","Use Baixar dossiê final somente quando não houver pendências. Se estiver incompleto, use Baixar ZIP parcial · INCOMPLETO: confira os arquivos, INDICE.csv, MANIFESTO.json e PENDENCIAS.txt antes de compartilhar.","Consulte Histórico de exportações para conferir quando o pacote foi preparado e as pendências registradas."],"result":"O ZIP contém os arquivos nativos com nomes padronizados e índice. O pacote parcial leva INCOMPLETO no nome; o final é bloqueado quando há pendências ou falha ao ler um arquivo.","attention":"Anexo ausente, vencimento, situação pendente ou aplicabilidade indefinida impedem o final. O pacote é montado no navegador com limite de 100 MB; arquivos não lidos no parcial constam nas pendências. A exportação baixa o ZIP e não o envia automaticamente à Prefeitura ou ao cartório. A conferência interna não equivale à aprovação do órgão. Edição e exportação exigem administrador ou engenheiro autorizado."},{"id":"licenca","title":"Licenciamento","purpose":"Acompanhar as exigências e etapas de aprovação da obra com evidências documentais.","before":"Selecione a obra e confira o tipo de licença, os órgãos e o condomínio envolvidos.","steps":["Use o lápis Editar exigência para abrir o item correto do checklist.","Anexe os documentos nos itens corretos e atualize a situação conforme a evidência.","Em Arquivos, escolha Dossiê de licenciamento para cadastrar responsável, validade e aplicabilidade, revisar anexos e consultar a documentação faltante.","Prepare o ZIP final quando estiver completo ou um ZIP parcial INCOMPLETO com a relação de pendências; confira o pacote antes de encaminhar ao órgão."],"result":"Cada etapa mostra a situação e os anexos correspondentes, compartilhados com o dossiê em Arquivos.","attention":"Anexar um documento ou concluir a conferência interna não comprova aprovação do órgão. O ZIP é baixado para conferência e envio manual; o sistema não protocola a documentação automaticamente."}]){const current=HELP_GUIDES.find(item=>item.id===published.id);if(current)Object.assign(current,published);else HELP_GUIDES.push(published);}
HELP_GUIDES.push(guide('cmp_contratos','Compras · Contratos e medições','Consultar contratos de fornecimento e acompanhar serviços medidos.','Confira a obra, o fornecedor e seu acesso aos serviços de terceiros.', 'Em Contratos e medições, escolha Fornecimento ou Serviços e medições.|Em Fornecimento, use Novo contrato quando autorizado; confira fornecedor, vigência, itens, preços e quantidades.|Use Adicionar insumo e Remover insumo para ajustar os itens do formulário; confira o total e use Salvar contrato.|Em Serviços e medições, revise os filtros e abra Ficha do contrato para consultar valores contratados, aprovados, baixados e a pagar.', 'O contrato e seu histórico ficam identificados no recorte escolhido.', 'Alterar o formulário não salva automaticamente. O acesso aos serviços e às medições depende do perfil; contrato de fornecimento não confirma entrega nem pagamento.'));
HELP_GUIDES.push(guide('cmp_ficha','Compras · Ficha rápida','Consultar e continuar uma compra sem reconstruir a pesquisa.','Confira a obra e os filtros da fila.', 'Clique no código na Tabela ou no Kanban. A ficha abre à direita; no celular, ocupa a tela.|Confira etapa, prazo e responsável. Em pedidos, compare Valor do pedido, Pago e Saldo a pagar; adiantamentos aparecem em aviso.|Use a próxima ação. Cancelar um formulário curto retoma a ficha; na área completa, use Voltar para para retomar a origem.|Voltar à fila, Fechar ou Escape encerram a consulta, mantendo busca, filtros e página.', 'Consultar não grava; a operação exige confirmação no formulário.', 'Receber não paga. Sem confirmação, repita o mesmo botão na ficha aberta. Após recarregar, use Retomar trabalho salvo para a confirmação pendente.'));
HELP_GUIDES.push(guide('fin_ficha','Financeiro · Ficha rápida','Conferir o compromisso e a ação permitida.','Confira obra, movimentação e prazo em Hoje.', 'Clique no nome na Tabela ou no Kanban.|Compare Valor original, Liquidado e Saldo em aberto. Vencimento inválido fica em Sem vencimento.|Se houver pagamento do pedido sem vínculo, use Alocar adiantamento e revise antes de pagar.|Use a próxima ação. Na conferência fiscal, feche a ficha fiscal e use Voltar à fila financeira para retomar a origem.|Consultar detalhamento abre origem e documentos; Fechar memorial retoma a ficha. Voltar à fila, Fechar ou Escape encerram a consulta.', 'O recorte da sessão é conservado; consultar não registra pagamento.', 'A ação depende do perfil e da obra. Registrar pagamento não executa transferência bancária. Se o título sair do recorte, volte à fila para conferir os saldos.'));
HELP_GUIDES.push(paymentGuide('cmp_pagamento','Compras · Registrar pagamento'));
