for(const area of ['fin','cmp']){
 HELP_GUIDES.push(guide(`${area}_recuperacao`,'Retomar trabalho salvo','Recuperar trabalho salvo.','Entre com o mesmo usuário, navegador e endereço do app.', 'Use Retomar trabalho salvo e confira obra e registro.|Rascunho não enviado: use Reabrir rascunho e revise antes de confirmar.|Confirmação enviada, sem resposta: confira o histórico e use Retomar confirmação para reenviar a operação original.', 'A confirmação atualiza o registro; abrir o rascunho não grava.', 'A recarga não envia automaticamente. Não é backup: depende dos dados locais. Abas compartilham o rascunho. Sem armazenamento, o envio é bloqueado. Obra e acesso seguem o registro atual. Registro indisponível mantém o trabalho salvo; confira a origem e as permissões. Se o armazenamento falhar na retomada, mantenha a ficha aberta e confira o histórico antes de outra operação. Em abas antigas, copie edições não salvas antes de recarregar após a atualização do ERP.'));
}
HELP_GUIDES.push(guide('home_recuperacao','Recuperar salvamento','Retomar uma edição protegida sem perder campos nem repetir ações.','Use a mesma conta, navegador e endereço. A recuperação procura primeiro a edição desta aba e depois a mais recente da mesma conta. Confira a conexão.', 'Antes de recuperar, salve ou cancele campos novos de outros formulários. Tentativas de salvar enquanto há outra pendência ficam protegidas separadamente.|Use Resolver salvamento no aviso ou no formulário aberto.|Se a sessão expirou, informe a senha da mesma conta em Renovar sessão; isso não grava automaticamente.|Use Consultar versão atual. Confira sua edição e o servidor; escolha cada campo em conflito. Nos demais campos, Manter servidor permite retirar uma mudança da revisão.|Use Salvar alterações revisadas e aguarde. Depois da recuperação, feche e reabra formulários antigos antes de editar novamente. Confira se outra edição aparece em Resolver salvamento e conclua as revisões até o aviso desaparecer.', 'A edição é enviada apenas após revisão explícita; a recarga não confirma operações.', 'A proteção depende do armazenamento local e não é backup. Sem armazenamento, o envio fica bloqueado: mantenha a aba aberta. Verificar armazenamento retoma a conferência inicial; Proteger preenchimentos tenta gravar as tentativas que ficaram na memória; Proteger e reenviar edição tenta proteger novamente o que está na memória. Descartar edição da memória exige confirmação e perde essa tentativa; cópias já protegidas são preservadas. Sair e trocar de conta aguardam envios em andamento. Resolva o armazenamento antes de sair com uma edição apenas na memória. Concluir conferência encerra uma pendência que já consta no servidor, sem repetir a gravação. Mudança de acesso ou obra pode bloquear a retomada. Descartar edição protegida consulta o servidor e remove apenas a edição revisada; confirme com cuidado. Pagamentos e recebimentos continuam usando suas confirmações próprias.'));

export const HELP_GLOSSARY = [
 ['Competência','Mês de referência de uma receita ou custo, que pode ser diferente do mês em que o dinheiro entrou ou saiu.'],
 ['DRE','Demonstração do Resultado: compara receitas, custos e despesas de um período.'],
 ['Conciliação','Conferência que relaciona uma linha do extrato bancário a um registro do sistema.'],
 ['RDO','Relatório Diário de Obra: registro das atividades e ocorrências de um dia.'],
 ['Lead','Pessoa ou empresa que pode se tornar cliente.'],
 ['Pipeline ou funil','Sequência de etapas pelas quais uma oportunidade comercial passa.'],
 ['FVS / FVM','Fichas de Verificação de Serviço e de Material, usadas na conferência de qualidade.'],
 ['Linha de base','Versão de referência do planejamento para comparar o previsto com o realizado.'],
 ['Curva A','Grupo de itens de maior peso financeiro, que merece atenção prioritária.'],
 ['Lotação','Obra à qual o funcionário está vinculado administrativamente; pode ser diferente da obra de captura do ponto.'],
];
export function normalizeHelp(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
export function searchHelp(guides, query){
 const words=normalizeHelp(query).trim().split(/\s+/).filter(Boolean);
 return guides.filter(item=>{const text=normalizeHelp([item.title,item.purpose,item.before,...item.steps,item.result,item.attention,item.example,...(item.responsibilities||[]).flat(),...(item.exceptions||[]).flat()].join(' '));return words.every(word=>text.includes(word));});
}
export {PURCHASE_HELP,FINANCE_HELP,WORK_HELP} from './help-topics.js';
// Indicadores de prazo operacional integrados ao Planejamento e ao Diário.
for(const id of ['fin_previsoes_kpis','fin_previsoes_executive']){
 const topic=HELP_GUIDES.find(item=>item.id===id);
 topic.steps.push('Em Indicadores da obra ou em Relatório para diretoria → Execução, confira Prazo da obra. Leia Atividades vencidas com saldo confirmado, Vencidas sem medição confirmada, Entregas nos próximos 7 dias e Cobertura das atividades pelo diário. O recorte é a Data de referência da previsão; o período inicial não limita o último avanço acumulado consultado.');
 topic.steps.push('Abra Conferir atividades, marcos e semanas. Em Memória do prazo por atividade, confira identificação, datas vigentes, avanço, diário e data da medição. Corrija as datas no Planejamento e faça o levantamento no Diário de obra; conclua o relatório com revisão técnica para que a medição seja reaproveitada. Consultar os indicadores não grava nem conclui o diário.');
 topic.steps.push('Confira Marcos do planejamento e Confiabilidade semanal do planejamento. Uma data de marco passada exige confirmação da entrega na origem. O percentual de planos concluídos (PPC) usa compromissos elegíveis no prazo, apenas de semanas inteiras encerradas e verificadas; bloqueados e fechamentos pendentes ficam separados.');
 const deadlineSteps=topic.steps.splice(-3);
 const exportIndex=topic.steps.findIndex(step=>step.includes('Exportar'));
 topic.steps.splice(exportIndex<0?topic.steps.length:exportIndex,0,...deadlineSteps);
 topic.attention+=' Atividades com datas ou identificação inválidas exigem correção no Planejamento; ficam fora das contagens de vencimento e próximas entregas. Prazo usa o último avanço acumulado em diário concluído e revisado, até a referência, vinculado pela identificação exata da atividade. Progresso digitado no Planejamento não substitui essa evidência. Sem medição não significa avanço zero nem atraso confirmado. Diários duplicados ou medição inválida exigem conferência. Dias de atraso são corridos desde o fim vigente; não estimam atraso de conclusão da obra. A data de conclusão é o primeiro registro de 100% do ciclo atual e pode ser posterior à execução. Desvio positivo contra a fotografia da base significa postergação das datas, não atraso realizado. A fotografia atual pode ser substituída e não reconstrói versões passadas. SPI (índice de desempenho de prazo) permanece indisponível: depende de valores planejados aprovados, versionados e comparáveis ao avanço.';
 topic.result+=' Os indicadores de prazo e sua memória acompanham os dados de origem carregados, sem formulário adicional.';
}
