executiveDeadlineHelp.steps=executiveDeadlineHelp.steps.map(step=>step.replace('as 20 seções','as 23 seções').replace('incluindo Inadimplência,','incluindo Prazos, Atividades prazo, Marcos prazo, Inadimplência,'));
